<script setup lang="ts">
import { onMounted, ref } from 'vue';
import QRCode from 'qrcode';
import { PluginCatalogueSchema,PluginRecordSchema,PluginStatusSchema,PluginQrSchema,PluginQrPollSchema,pluginMetadata,type PluginRecord,type PluginId } from '../../../../packages/contracts/src/plugins';
import { ReminiscenceOverviewSchema } from '../../../../packages/contracts/src/plugins/reminiscence';
import { runtimeRequest,runtimeAction } from '../../api/typescript';
import { confirmDestructiveAction, confirmUnsavedDrafts, useUnsavedDraft } from '../../composables/unsaved';
import PluginSubscriptions from './PluginSubscriptions.vue';
import QQFileSettings from './QQFileSettings.vue';
import MarkdownSettings from './MarkdownSettings.vue';
import BilibiliSettings from './BilibiliSettings.vue';
import BangumiSettings from './BangumiSettings.vue';
import ReminiscenceSettings from './ReminiscenceSettings.vue';
const catalogue=ref(PluginCatalogueSchema.parse({plugins:[]}));const draft=ref<PluginRecord>();const baseline=ref('');const error=ref('');const notice=ref('');const busy=ref(false);const details=ref<{label:string;value:string}[]>([]);const overview=ref<ReturnType<typeof ReminiscenceOverviewSchema.parse>>();
const qr=ref<ReturnType<typeof PluginQrSchema.parse>>();const qrImage=ref('');const loginStatus=ref('');
const { dirty, markSaved, confirmDiscard } = useUnsavedDraft('插件配置', () => draft.value, '/plugins');
async function action(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await work();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function refresh(){catalogue.value=await runtimeRequest('plugins',PluginCatalogueSchema);}
async function refreshStatus(){await action(async()=>{await refresh();if(draft.value)await status(draft.value.id);});}
async function reloadSettings(){if(busy.value || !draft.value || !confirmDiscard())return;const id=draft.value.id;await action(async()=>{draft.value=await runtimeRequest(`plugins/${id}`,PluginRecordSchema);baseline.value=JSON.stringify(draft.value);markSaved();await status(id);notice.value='已载入服务器保存的插件配置。';});}
async function status(id:PluginId){details.value=(await runtimeRequest(`plugins/${id}/status`,PluginStatusSchema)).details;if(id==='local_reminiscence')overview.value=await runtimeRequest(`plugins/${id}/records`,ReminiscenceOverviewSchema);}
async function select(id:PluginId){if(busy.value || draft.value?.id===id || !confirmUnsavedDrafts('/plugins'))return;await action(async()=>{const loaded=await runtimeRequest(`plugins/${id}`,PluginRecordSchema);draft.value=loaded;baseline.value=JSON.stringify(loaded);markSaved();details.value=[];overview.value=undefined;qr.value=undefined;qrImage.value='';loginStatus.value='';await status(id);});}
async function save(){await action(async()=>{if(!draft.value)return;const data=PluginRecordSchema.parse(draft.value);draft.value=await runtimeRequest(`plugins/${data.id}`,PluginRecordSchema,{expectedRevision:data.revision,settings:data.settings},'PUT');baseline.value=JSON.stringify(draft.value);markSaved();notice.value=`${pluginMetadata[data.id].name}配置已独立保存，后续调用使用新设置。`;await refresh();await status(data.id);});}
function discard(){if(busy.value || !baseline.value || !confirmDiscard())return;draft.value=PluginRecordSchema.parse(JSON.parse(baseline.value));markSaved();notice.value='已撤销当前插件的未保存修改。';}
async function login(){await action(async()=>{qr.value=await runtimeRequest('plugins/bili_video/login',PluginQrSchema,{});qrImage.value=await QRCode.toDataURL(qr.value.url,{width:240,margin:2});loginStatus.value='请使用哔哩哔哩 App 扫码。';});}
async function poll(){await action(async()=>{if(!qr.value)return;const result=await runtimeRequest('plugins/bili_video/login-poll',PluginQrPollSchema,{id:qr.value.id});loginStatus.value=({waiting:'等待扫码',scanned:'已扫码，请在手机确认',success:'登录成功',expired:'二维码已过期'})[result.status];if(result.status==='success'||result.status==='expired'){qr.value=undefined;qrImage.value='';}await status('bili_video');});}
async function logout(){if(busy.value||!confirmDestructiveAction('清除 Bilibili 扫码登录凭据？立即生效；外部 Cookie 密钥不会删除。'))return;await action(async()=>{await runtimeAction('plugins/bili_video/logout',{});qr.value=undefined;qrImage.value='';loginStatus.value='已清除扫码登录凭据。';await status('bili_video');});}
async function memoryAction(request:{operation:'daily'|'consolidate'|'reindex'|'delete_day';scopeKey:string;date:string}){if(busy.value)return;if(dirty.value){error.value='请先保存或撤销插件设置，再执行回忆管理操作。操作使用已保存的设置。';return;}if(request.operation==='delete_day'&&!confirmDestructiveAction(`删除 ${request.date} 在所选范围内的回忆和原始记录？此操作立即生效且无法恢复。`))return;await action(async()=>{overview.value=await runtimeRequest('plugins/local_reminiscence/records',ReminiscenceOverviewSchema,request);notice.value='记忆管理操作已完成，请查看任务状态。';});}
onMounted(()=>action(refresh));
</script>
<template><section class="plugin-workspace"><header class="toolbar"><div><h2>原生插件</h2><p class="muted">独立保存各插件设置。启用后，在 Agent 的资源与工具中装配需要的工具。</p></div><button :disabled="busy" @click="refreshStatus">刷新状态</button></header><p v-if="error" class="error-banner" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div class="plugin-layout"><nav class="plugin-list" aria-label="插件列表"><button v-for="plugin in catalogue.plugins" :key="plugin.id" :class="{selected:draft?.id===plugin.id}" :disabled="busy" @click="select(plugin.id)"><strong>{{plugin.name}}</strong><span>{{plugin.record.settings.enabled?'已启用':'已停用'}}</span><small>{{plugin.description}}</small></button></nav><section v-if="draft" class="plugin-editor"><div class="toolbar"><h3>{{pluginMetadata[draft.id].name}}</h3><a :href="pluginMetadata[draft.id].source" target="_blank" rel="noopener noreferrer">参考项目</a><span>r{{draft.revision}}{{dirty?' · 未保存':''}}</span><button type="button" :disabled="busy" @click="reloadSettings">重新载入配置</button></div><div class="plugin-status"><span v-for="item in details" :key="item.label">{{item.label}}：{{item.value}}</span></div><p class="muted" role="status">独立保存 · {{dirty?'有未保存修改':'已与服务器同步'}}。保存插件配置后，后续调用生效；刷新状态会保留当前编辑内容。</p><form @submit.prevent="save"><fieldset :disabled="busy"><QQFileSettings v-if="draft.id==='qq_file'" v-model="draft.settings"/><MarkdownSettings v-else-if="draft.id==='markdown_killer'" v-model="draft.settings"/><BilibiliSettings v-else-if="draft.id==='bili_video'" v-model="draft.settings" :login-status="loginStatus" :qr-url="qr?.url" :qr-image="qrImage" :busy="busy" @login="login" @poll="poll" @logout="logout"/><BangumiSettings v-else-if="draft.id==='bangumi'" v-model="draft.settings"/><ReminiscenceSettings v-else-if="draft.id==='local_reminiscence'" v-model="draft.settings" :overview="overview" @reload="action(()=>status('local_reminiscence'))" @action="memoryAction"/></fieldset><div class="toolbar plugin-save"><button type="submit" :disabled="busy||!dirty">{{busy?'处理中…':`保存${pluginMetadata[draft.id].name}配置`}}</button><button type="button" :disabled="busy||!dirty" @click="discard">撤销修改</button></div></form><PluginSubscriptions :key="draft.id" v-if="draft.id==='bili_video'||draft.id==='bangumi'" :id="draft.id"/><details><summary>工具和指令</summary><p class="muted">{{catalogue.plugins.find(item=>item.id===draft?.id)?.tools.join('、')||'此插件使用消息处理钩子，无模型工具。'}}</p><p>{{pluginMetadata[draft.id].commands.join('、')}}</p></details></section><div v-else class="muted">选择插件，查看配置和运行状态。</div></div></section></template>
<style scoped>
.plugin-workspace{display:grid;gap:18px}.plugin-layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:24px;align-items:start}.plugin-list{display:grid;gap:10px}.plugin-list button{display:grid;grid-template-columns:1fr auto;gap:8px;text-align:left;padding:16px;border:1px solid var(--ts-border,#d7e4dc);background:var(--ts-surface,#fff);border-radius:12px;color:inherit}.plugin-list button.selected{border-color:#38805b;background:#ecf6ef}.plugin-list small{grid-column:1/-1;line-height:1.6;color:#738177}.plugin-list span{font-size:11px;color:#39785a}.plugin-editor{display:grid;gap:16px;min-width:0}.plugin-status{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;color:#607568}fieldset{border:0;padding:0;margin:0;min-width:0}.plugin-save{margin-top:22px;position:sticky;bottom:12px;background:#f1f8f3;padding:12px;border:1px solid #dae6de;border-radius:10px}.muted{overflow-wrap:anywhere}h2,h3{margin:0}@media(max-width:900px){.plugin-layout{grid-template-columns:1fr}.plugin-list{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:500px){.plugin-list{grid-template-columns:1fr}}
</style>
